    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    initial begin
        clk = 0;
        reset = 1;
        #12;

        // Check reset state
        if (q !== 16'h0000) begin
            errors = errors + 1;
            $display("FAIL: Reset state q is %h, expected 16'h0000", q);
        end
