            errors = errors + 1;
            $display("FAIL: Reset state ena is %b, expected 4'b0000", ena);
        end

        // Release reset
        reset = 0;
        #2;

        // Run through a few clock cycles to test normal increments and enables
        // Cycle 1: q becomes 1, ena[0] should be 0 (since previous q[3:0] was 0, wait, 
        // let's trace: at reset q[3:0]=0. On posedge, q[3:0] != 9, so q[3:0] <= 0+1=1, ena[0] <= 0).
        @(posedge clk);
        #1;
        if (q[3:0] !== 4'd1) begin
            errors = errors + 1;
            $display("FAIL: q[3:0] expected 1, got %d", q[3:0]);
        end

